753	                    }
754	                    p = std::future::poll_fn(|cx| Pin::new(&mut pages).poll_next(cx)) => p,
755	                },
756	                None => std::future::poll_fn(|cx| Pin::new(&mut pages).poll_next(cx)).await,
757	            };
758	            match page {
759	                Some(Ok(page)) => {
760	                    if page.records.is_empty() && page.bookmark.is_none() {
761	                        continue;
762	                    }
