import re
p = "docs/book/src/getting-started/learn.md"
s = open(p).read()

def new_block(body):
    b = body
    if "config → compose" in b:
        d = 'flowchart LR\n    cfg["config"] --> comp["compose"] --> interp["interpolate"] --> sec["secrets"] --> parse["parse"] --> exp["expand"] --> exe["executor"] --> pipe["Pipeline"] --> rs["run_stream"]'
    elif "[write path]" in b:
        d = 'flowchart LR\n    PAGE["page"] --> M["mask"] --> Q["quality"] --> C["contract"] --> D["drift"] --> WR["write path"] --> FL["flush"] --> CK["checkpoint"]'
    elif "page 1" in b:
        d = 'flowchart LR\n    P1["page 1"] --> W1["write"] --> P2["page 2"] --> W2["write"] --> P3["page 3<br/>+ bookmark"] --> W3["write"] --> F["flush"] --> CK["save bookmark"]'
    elif "save bookmark" in b:
        d = 'flowchart LR\n    PAGE["page"] --> M["mask"] --> Q["quality"] --> C["contract"] --> D["drift"] --> W["write"] --> FL["flush"] --> CK["save bookmark"]'
    elif "source.fetch" in b:
        d = 'flowchart LR\n    A["source.fetch<br/>read all"] --> B["sink.write"] --> C["done — wrote N records"]'
    elif "Source" in b and "records" in b:
        d = 'flowchart LR\n    S["Source"] -->|records| P["faucet pipeline"] -->|records| K["Sink"]'
    else:
        return None
    return "```mermaid\n" + d + "\n```"

def repl(m):
    nb = new_block(m.group(1))
    return nb if nb else m.group(0)

s2, n = re.subn(r"```text\n(.*?)\n```", repl, s, flags=re.S)
open(p, "w").write(s2)
print("converted", s.count("```text") - s2.count("```text"), "text blocks to mermaid")
print("remaining ```text in learn.md:", s2.count("```text"))
print("```mermaid blocks now:", s2.count("```mermaid"))
PY

