47	    pub fn badge(self) -> &'static str {
48	        match self {
49	            Tier::Stable => "🟢",
50	            Tier::Experimental => "🟡",
51	            Tier::Beta => "🟠",
52	            Tier::Draft => "⚪",
53	        }
54	    }
