56	    /// Derive the tier from a 0–100 conformance score.
57	    pub fn from_score(score: u32) -> Tier {
58	        match score {
59	            70..=u32::MAX => Tier::Stable,
60	            45..=69 => Tier::Experimental,
61	            20..=44 => Tier::Beta,
62	            _ => Tier::Draft,
