.fs-hero .fs-tagline {
  font-size: 1.35rem;
  font-weight: 500;
  margin: 1rem auto 1.5rem;
  max-width: 34rem;
  line-height: 1.45;
}
.fs-hero .fs-tagline strong,
.fs-hero .fs-tagline b {
  background: linear-gradient(90deg, var(--fs-teal), var(--fs-cyan));
