.fs-cta a.primary {
  background: linear-gradient(135deg, var(--fs-teal), var(--fs-teal-deep));
  color: #fff !important;
  box-shadow: 0 6px 18px color-mix(in srgb, var(--fs-teal) 35%, transparent);
