/* ── Hero ─────────────────────────────────────────────────────────────── */
.hero { position: relative; overflow: hidden; border-bottom: 1px solid var(--line); }
#flow { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 0; opacity: .5; }
.hero .wrap { position: relative; z-index: 1; padding-block: clamp(3.5rem, 10vw, 7rem); }
.hero-name {
  font-size: clamp(2.6rem, 8vw, 5rem);
  font-weight: 800;
  margin: 0;
  letter-spacing: -0.035em;
}
.hero-role {
  font-family: var(--mono);
  font-size: clamp(.9rem, 2.2vw, 1.05rem);
  color: var(--ink-2);
  margin: 1rem 0 0;
  letter-spacing: .01em;
}
.hero-role b { color: var(--signal); font-weight: 600; }
.hero-lede {
  font-size: clamp(1.15rem, 2.6vw, 1.5rem);
  color: var(--ink);
  max-width: 40ch;
  margin: 1.6rem 0 2rem;
  font-weight: 450;
  line-height: 1.4;
}
.hero-lede em { color: var(--accent-ink); font-style: normal; font-weight: 650; }
.actions { display: flex; flex-wrap: wrap; gap: .7rem; }
.btn {
  font-family: var(--mono); font-size: .85rem; font-weight: 600;

