/* ── Lower-section polish ─────────────────────────────────────────────────── */
/* Guard the full-bleed 100vw bands below from creating horizontal scroll. */
html { overflow-x: hidden; }
/* Scroll rhythm: alternating full-bleed bands carry the hero's blue downward
   so the lower sections read as distinct movements, not one flat white sheet. */
main > section { position: relative; }
main > section:nth-of-type(even)::before {
  content: ""; position: absolute; z-index: -1; inset-block: 0;
  left: 50%; margin-left: -50vw; width: 100vw;
  background: color-mix(in srgb, var(--accent) 5%, var(--paper));
  border-block: 1px solid color-mix(in srgb, var(--accent) 12%, transparent);
}
/* Cards + the feature block: soft lift and an accent edge on hover. */
.card, .feature { transition: transform .18s ease, box-shadow .18s ease, border-color .18s ease; }
.card:hover, .feature:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 28px color-mix(in srgb, var(--accent) 16%, transparent);
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
}
/* Certification rows: gentle accent wash + nudge on hover. */
.cert { border-radius: 8px; transition: background .15s ease, padding-left .15s ease; }
.cert:hover { background: color-mix(in srgb, var(--accent) 7%, transparent); padding-left: .6rem; }
/* Skill/tech chips pick up the accent on hover. */
.chip, .taglist span { transition: border-color .15s ease, color .15s ease; }
.chip:hover, .taglist span:hover {
  border-color: color-mix(in srgb, var(--accent) 50%, var(--line));
  color: var(--accent-ink);
}
@media (prefers-reduced-motion: reduce) {
  .card, .feature, .cert { transition: none; }
  .card:hover, .feature:hover { transform: none; }
}

