python3 - <<'PY'
import glob, re
files = glob.glob("docs/book/book/css/*.css") + glob.glob("docs/book/book/custom-*.css")
def blueish(h):
    r,g,b = int(h[1:3],16),int(h[3:5],16),int(h[5:7],16)
    return (b > r+25 and b > g) or (b>r+20 and r>g+20)  # blue OR purple (high R+B, low G)
# 1) any :visited rules
print("=== :visited rules ===")
for f in files:
    css=open(f).read()
    for m in re.finditer(r'([^{}]*:visited[^{}]*)\{([^}]*)\}', css):
        print(f.split('/')[-1], m.group(1).strip()[:70], '{', m.group(2).strip()[:60], '}')
# 2) sidebar/chapter/toggle rules that set a blue/purple color
print("\n=== sidebar/chapter/toggle color rules with blue/purple ===")
for f in files:
    css=open(f).read()
    for m in re.finditer(r'([^{}]*(chapter|sidebar|toggle|\.section)[^{}]*)\{([^}]*)\}', css):
        body=m.group(3)
        for hx in re.findall(r'#[0-9a-fA-F]{6}', body):
            if blueish(hx.lower()):
                print(f.split('/')[-1], m.group(1).strip()[:60], '→', hx)
PY
rm -rf docs/book/book

