  --sidebar-fg: #e4eaef; /* light neutral slate — crisp, NOT teal-on-teal */
  --sidebar-non-existant: #7f96a0;
  --sidebar-active: #ffffff;
  --sidebar-spacer: rgba(255, 255, 255, 0.1);
  --scrollbar: rgba(255, 255, 255, 0.28);
